     5→export async function GET(_req: NextRequest): Promise<NextResponse> {
     6→  try {
     7→    const db = getDb();
     8→    const rows = db
     9→      .prepare('SELECT * FROM to_haejung ORDER BY college, id')
    10→      .all() as ToHaejungRow[];
    11→    return NextResponse.json(rows);
    12→  } catch (err) {
    13→    return NextResponse.json(
    14→      { error: err instanceof Error ? err.message : '조회 실패' },
    15→      { status: 500 }
    16→    );
    17→  }
    18→}
